"""Rebuild the inline glossary and reading route, keeping the rest of the guide."""
from pathlib import Path
from html import escape
from bs4 import BeautifulSoup

ROOT=Path(__file__).resolve().parent
ROS='https://github.com/ros2/ros2_documentation/blob/humble/source/'
MOVEIT='https://moveit.picknik.ai/humble/doc/'
CONTROL='https://control.ros.org/humble/doc/'
REPO='https://github.com/REZ3LIET/KUKA-ROS2/blob/8f2c2a35a2d45d5739c7a247d5872e514a8d4895/'
DRIVERS='https://github.com/kroshu/kuka_drivers/blob/humble/'

# Category, term, plain-language definition, role in this project, primary reference, search aliases.
TERMS=[
('fundamentos','ROS 2','Conjunto de bibliotecas y herramientas para construir aplicaciones robóticas mediante componentes que intercambian datos. No es el sistema operativo del controlador KUKA.','Conecta los procesos de la aplicación: puente, planificación, control y lectura del estado.',ROS+'Concepts/Basic/About-Nodes.rst','ros2 robot operating system middleware'),
('fundamentos','ROS 2 Humble','Distribución de ROS 2: una combinación versionada de paquetes y herramientas. La base acordada de esta guía es Humble con Ubuntu 22.04.','Elegir ramas, dependencias y documentación Humble; no mezclar instrucciones de otras distribuciones sin revisar compatibilidad.',ROS+'Releases/Release-Humble-Hawksbill.rst','humble hawksbill ubuntu distro version'),
('fundamentos','Nodo','Participante del grafo ROS 2 que realiza una función y se comunica con otros nodos. Varios nodos pueden compartir un proceso o estar en equipos diferentes.','Ejemplos: robot_state_publisher, move_group y el servidor de tareas.',ROS+'Concepts/Basic/About-Nodes.rst','node proceso grafo'),
('fundamentos','Tópico','Canal con nombre por el que se publican y reciben mensajes. Se usa habitualmente para flujos continuos de datos.','El estado articular puede publicarse en /arm_1/joint_states.',ROS+'Concepts/Basic/About-Topics.rst','topic publicar suscribir publisher subscriber'),
('fundamentos','Mensaje / .msg','Definición de los campos y tipos de un dato ROS. El mensaje es la estructura del dato; el tópico es el canal por el que puede circular.','JointState y Joints.msg tienen contratos distintos. Un Action.msg publicado en un tópico no invoca automáticamente una acción.',ROS+'Concepts/Basic/About-Interfaces.rst','message tipo contrato interface interfaz msg'),
('fundamentos','Servicio / .srv','Intercambio de solicitud y respuesta, pensado para operaciones que terminan pronto.','Consultar o configurar una función no exige usar el mismo mecanismo que una tarea de movimiento larga.',ROS+'Concepts/Basic/About-Services.rst','service solicitud respuesta request response'),
('fundamentos','Acción / .action','Contrato para tareas de mayor duración: envía un objetivo, puede devolver progreso y termina con un resultado. Incluye mecanismos de cancelación.','/Move es una acción personalizada. Deben distinguirse objetivo aceptado, ejecución terminada y fallo.',ROS+'Concepts/Basic/About-Actions.rst','action goal feedback result cancelar'),
('fundamentos','Parámetro','Valor de configuración asociado a un nodo. Cambia ajustes del proceso; no es un canal de mensajes de movimiento.','use_sim_time es un parámetro. Su valor debe ser coherente con el reloj del backend.',ROS+'Concepts/Basic/About-Parameters.rst','parameter configuracion'),
('fundamentos','Paquete ROS','Unidad que agrupa código, interfaces, configuración y metadatos de una funcionalidad.','kuka_gazebo, control_actions y control_scripts son paquetes con responsabilidades diferentes.',ROS+'Tutorials/Beginner-Client-Libraries/Creating-Your-First-ROS2-Package.rst','package package.xml cmakelists'),
('fundamentos','Workspace, overlay y colcon','El workspace organiza los paquetes. colcon los compila; cargar install/setup.bash incorpora ese overlay al entorno de la terminal.','Los nodos y RosBridge deben poder encontrar la misma versión compilada de control_actions.',ROS+'Tutorials/Beginner-Client-Libraries/Creating-A-Workspace/Creating-A-Workspace.rst','espacio trabajo build source setup bash compilacion'),
('fundamentos','Launch / .launch.py','Archivo que organiza el arranque de nodos, sus argumentos, parámetros y relaciones de inicio. No es una trayectoria.','multi_kuka_bringup.launch.py incluye el bringup por cada instancia definida en robot_list.',ROS+'Tutorials/Intermediate/Launch/Using-ROS2-Launch-For-Large-Projects.rst','lanzador arranque launch python'),
('fundamentos','YAML / YML','Formato de datos usado para escribir configuraciones legibles. YAML y YML son extensiones del mismo formato; el papel lo decide quien lee el archivo.','Un YAML configura controladores y otro configura MoveIt. No todos son programas de movimiento ni se cargan solos.',REPO+'kuka_gazebo/config/kuka_controllers.yaml','yaml yml configuracion ros__parameters'),
('red','DDS','Data Distribution Service: tecnología de comunicación distribuida que usa el middleware habitual de ROS 2 para descubrir participantes e intercambiar datos.','Permite que nodos compatibles se encuentren; no sustituye el protocolo externo del controlador KUKA.',ROS+'Concepts/Intermediate/About-Different-Middleware-Vendors.rst','data distribution service descubrimiento multicast'),
('red','RMW','Capa de abstracción entre las bibliotecas de ROS 2 y una implementación de middleware. No es otro nombre para RosBridge.','La implementación y su configuración influyen en descubrimiento y transporte. Hay que comprobarlas al diagnosticar comunicaciones.',ROS+'Concepts/Intermediate/About-Different-Middleware-Vendors.rst','rmw fastdds cyclone middleware'),
('red','ROS_DOMAIN_ID','Identificador que separa dominios de descubrimiento DDS. En condiciones normales, nodos en dominios diferentes no se descubren directamente.','Dominio 30 es sólo el ejemplo de esta guía. Cambiarlo no cambia la IP de KUKA ni libera un puerto WebSocket ocupado.',ROS+'Concepts/Intermediate/About-Domain-ID.rst','domain id dominio domain_id ros domain identificador'),
('red','Namespace','Prefijo que organiza nombres de nodos, tópicos, servicios y acciones dentro del grafo. No cambia automáticamente un nombre absoluto escrito en el código.','/arm_1 y /arm_3 separan rutas si toda la cadena respeta esos nombres. El /Move absoluto del repositorio exige revisión.',ROS+'How-To-Guides/Node-arguments.rst','espacio nombres namespace nombres absoluto relativo'),
('red','Remapping','Regla que cambia el nombre de una interfaz ROS al iniciar un nodo. Es un ajuste de nombres, no un puente entre dominios.','Puede ayudar a dirigir una ruta, pero debe revisarse junto con los nodos internos, los namespaces y los clientes.', 'https://design.ros2.org/articles/static_remapping.html','remap renombrar redireccionar'),
('red','IP y subred','La dirección IP identifica una interfaz de red. La subred define qué direcciones se consideran locales según una máscara.','PC y controladores requieren direcciones propias y conectividad. El laboratorio supone una red /24 sin router; no describe todas las redes posibles.',DRIVERS+'doc/wiki/2_RSI.md','ethernet ipv4 direccion mascara red subnet'),
('red','Puerto','Número que ayuda a identificar un extremo de comunicación de una aplicación o protocolo en un equipo. No equivale a un namespace ni a un dominio DDS.','9090 es el puerto WebSocket ilustrativo. Los puertos del driver KUKA se definen por separado.',ROS+'Concepts/Intermediate/About-Domain-ID.rst','port tcp udp socket endpoint'),
('red','QoS','Quality of Service: políticas de entrega, fiabilidad, historial y otros comportamientos de comunicación. Emisor y receptor necesitan ajustes compatibles.','Un mismo nombre de tópico y dominio no garantizan recepción si las políticas QoS son incompatibles.',ROS+'Concepts/Intermediate/About-Quality-of-Service-Settings.rst','quality of service reliable best effort calidad servicio'),
('red','RosBridge','Puente que expone interfaces ROS mediante un protocolo basado en JSON y transportes como WebSocket. No reemplaza el driver de hardware.','Permite que un cliente Unity intercambie datos con ROS 2. El soporte de acciones debe comprobarse en las versiones elegidas.', 'https://github.com/RobotWebTools/rosbridge_suite/blob/humble/README.md','rosbridge bridge puente servidor'),
('red','WebSocket','Protocolo para mantener una comunicación bidireccional entre cliente y servidor sobre una conexión. Es el transporte, no la definición de una tarea robótica.','Unity puede usar ws://IP_DEL_PC:9090 para llegar a RosBridge; ese enlace no constituye el ciclo industrial del robot.', 'https://www.rfc-editor.org/rfc/rfc6455','ws websocket transporte conexion'),
('red','JSON','Formato de texto para intercambiar datos estructurados: campos, números, listas y objetos. Por sí solo no especifica unidades ni cómo mover un brazo.','RosBridge interpreta operaciones y datos JSON conforme a su protocolo y a los tipos ROS disponibles.', 'https://www.rfc-editor.org/rfc/rfc8259','serializacion formato json'),
('red','ROS# / cliente C#','Biblioteca y herramientas de Siemens para integrar aplicaciones .NET o Unity con ROS, incluyendo cliente de puente y generación de mensajes.','Revisar la versión usada y generar tipos compatibles con ROS 2 y con las interfaces personalizadas del proyecto.', 'https://github.com/siemens/ros-sharp','ros sharp rosshARP csharp c# unity cliente'),
('modelos','Unity','Motor y entorno de desarrollo para escenas 3D e interfaces interactivas. Una escena visual no es, por sí sola, una conexión física.','Contiene la interfaz actual de la celda y sus modelos. Debe separar el objetivo solicitado del estado que devuelve el robot.', 'https://docs.unity3d.com/Manual/','interfaz editor escena gemelo digital'),
('modelos','Gazebo Fortress / Ignition','Simulador de robótica con mundo físico virtual. Fortress pertenece a la generación que también se denominó Ignition Gazebo.','Es el backend de simulación del repositorio KUKA revisado, combinado allí con ROS 2 Humble. Mover un modelo no acredita ejecución real.', 'https://gazebosim.org/docs/fortress/ros_installation/','gazebo ignition fortress simulacion mundo sdf'),
('modelos','RViz','Herramienta de visualización de datos ROS: modelos, referencias, estados y resultados de planificación. No equivale a un simulador de dinámica.','Puede mostrar el robot y ayudar a inspeccionar la planificación de MoveIt; Gazebo cumple otro papel.',MOVEIT+'concepts/move_group.html','rviz rviz2 visualizacion'),
('modelos','URDF y Xacro','URDF describe eslabones y articulaciones del robot. Xacro permite generar esa descripción mediante macros y parámetros.','Revisar nombres, geometría, límites y configuración ros2_control. El archivo de descripción no crea el driver físico.',MOVEIT+'examples/urdf_srdf/urdf_srdf_tutorial.html','urdf xacro link joint modelo descripcion'),
('modelos','SRDF y grupo de planificación','SRDF complementa el modelo con información semántica, como grupos de articulaciones y configuraciones. MoveIt planifica para un grupo definido.','El grupo del brazo, su herramienta y las reglas de colisión deben corresponder al modelo y a la celda.',MOVEIT+'examples/urdf_srdf/urdf_srdf_tutorial.html','srdf planning group semantica colisiones'),
('modelos','TF / marco de referencia / TCP','Un marco define desde dónde se expresa una posición u orientación; TF relaciona marcos. El TCP es el punto de referencia de la herramienta.','Una pose debe indicar la base y herramienta usadas. Un namespace no prefija automáticamente los frame_id.',ROS+'Tutorials/Intermediate/Tf2/Introduction-To-Tf2.rst','tf tf2 frame base tool tcp coordenadas transformacion'),
('modelos','Pose, Euler y cuaternión','Una pose combina posición y orientación. Euler usa tres ángulos; un cuaternión representa la orientación con cuatro componentes. Las convenciones y unidades importan.','Unity y el adaptador deben acordar ejes, unidades y marco. MoveRP recibe ángulos en grados; los mensajes ROS habituales usan convenciones diferentes.', 'https://github.com/ros-infrastructure/rep/blob/master/rep-0103.rst','pose quaternion cuaternion yaw pitch roll euler grados radianes unidades'),
('modelos','Reloj simulado / use_sim_time','Un nodo puede usar el tiempo de simulación publicado en /clock en lugar del reloj normal. Todos los procesos implicados deben ser coherentes.','El bringup revisado fija este parámetro en algunos nodos. Pasar a hardware requiere revisar esa configuración y las marcas de tiempo.', 'https://design.ros2.org/articles/clock_and_time.html','clock use_sim_time reloj timestamp tiempo'),
('modelos','Mock / GenericSystem','Componente de prueba que imita interfaces de hardware, normalmente con comportamiento ideal. No mide ni acciona un robot físico.','Sirve para revisar la cadena de software sin hardware; no sustituye las pruebas con el controlador real.',CONTROL+'ros2_control/hardware_interface/doc/mock_components_userdoc.html','mock fake generic system backend virtual'),
('control','MoveIt 2','Conjunto de herramientas para planificación de movimiento y manipulación en ROS 2. Es MoveIt 2, no “Move2”, y no es la capa de comunicación DDS.','Puede calcular y ejecutar un plan mediante controladores compatibles. No habla automáticamente con cualquier controlador KUKA.',MOVEIT+'concepts/concepts.html','move2 move 2 moveit2 moveit planificador'),
('control','Cinemática directa e inversa','La directa calcula la pose a partir de las articulaciones. La inversa busca valores articulares que permitan alcanzar una pose.','Una solución cinemática no garantiza por sí sola un recorrido libre de colisiones o ejecutable.',MOVEIT+'concepts/kinematics.html','fk ik cinematica inversa directa'),
('control','Plan, camino y trayectoria','El camino describe por dónde pasar. La trayectoria añade la evolución temporal, por ejemplo posiciones articulares en instantes concretos.','Un controlador necesita consignas compatibles y tiempos. Un objetivo cartesiano no es todavía una trayectoria articular.',MOVEIT+'concepts/trajectory_processing.html','path trajectory plan waypoint tiempo trayectoria'),
('control','ros2_control','Marco que conecta algoritmos de control con interfaces de hardware o simulación, separando controladores y componentes de acceso al equipo.','En el repositorio se conecta a simulación o mock. Para hardware debe existir una interfaz compatible con el driver elegido.', 'https://github.com/ros-controls/ros2_control/blob/humble/README.md','ros2 control hardware interface plugin'),
('control','controller_manager','Componente que gestiona controladores y acceso a las interfaces de hardware. Su ciclo lee estado, actualiza control y escribe consignas.','Permite comprobar qué controladores están cargados o activos. Su frecuencia no debe confundirse con los FPS de Unity.',CONTROL+'ros2_control/controller_manager/doc/userdoc.html','controller manager gestor update rate hz'),
('control','JointTrajectoryController','Controlador que sigue trayectorias articulares con puntos definidos en el tiempo. No es un planificador de movimiento cartesiano.','kuka_arm_controller usa este tipo en el YAML revisado. Las articulaciones e interfaces deben coincidir con el backend.',CONTROL+'ros2_controllers/joint_trajectory_controller/doc/userdoc.html','joint trajectory controller kuka_arm_controller jtc'),
('control','FollowJointTrajectory','Acción estándar para solicitar la ejecución de una trayectoria articular y recibir resultado y seguimiento. Es diferente de la acción personalizada Move.','moveit_controllers.yaml conecta MoveIt con el endpoint follow_joint_trajectory del controlador.', 'https://github.com/ros-controls/control_msgs/blob/humble/control_msgs/action/FollowJointTrajectory.action','followjointtrajectory control_msgs action_ns'),
('control','JointState y broadcaster','JointState contiene nombres y valores articulares con una marca temporal. El broadcaster publica el estado disponible en ros2_control.','Unity debe asociar cada nombre con su valor y distinguir datos simulados de mediciones reales.', 'https://github.com/ros2/common_interfaces/blob/humble/sensor_msgs/msg/JointState.msg','jointstate joint_states joint_state_broadcaster realimentacion feedback'),
('control','Move, MoveJ, MoveL y MoveRP','Contrato y operaciones particulares de este repositorio: MoveJ usa objetivos articulares; MoveL, desplazamiento cartesiano; MoveRP, pose objetivo. No son una API universal de KUKA.','Conservar las unidades y semánticas del código. El apartado Archivos y mensajes explica sus campos y diferencias.',REPO+'kuka_control/control_scripts/src/move_robot.cpp','move movej movel moverp moveg control_actions velocidad speed'),
('control','PTP y LIN / Pilz','Modos de planificación industrial: PTP conecta configuraciones; LIN busca un desplazamiento rectilíneo del efector en el espacio cartesiano, sujeto a restricciones.','El código selecciona PTP para MoveJ/MoveRP y LIN para MoveL. Pedir una pose no implica automáticamente una línea recta.', 'https://github.com/moveit/moveit2/tree/humble/moveit_planners/pilz_industrial_motion_planner','ptp lin circ pilz interpolacion lineal'),
('kuka','Driver de hardware','Software que adapta consignas y lecturas ROS a una interfaz concreta del controlador físico. La compatibilidad depende del equipo y sus opciones.','Es la pieza que falta incorporar en el repositorio de simulación; no se obtiene sólo cambiando una IP.',DRIVERS+'README.md','driver adaptador hardware protocolo real'),
('kuka','Controlador KUKA y familia de sistema','Equipo que gobierna el brazo y ejecuta su software. KSS, Sunrise e iiQKA.OS2 son familias de sistema con interfaces y requisitos diferentes.','Identificar controlador, versión y opciones antes de escoger una ruta de comunicación; no deducirlos del modelo visual.', 'https://github.com/kuka-ros','krc kr c2 c4 c5 kss sunrise iiqka firmware controlador'),
('kuka','RSI','Robot Sensor Interface: opción KUKA para intercambio cíclico con una aplicación externa. Requiere una combinación admitida de controlador, versión y configuración.','Es una ruta posible para ciertos equipos; su ciclo se prepara en el driver, no en cada frame de Unity.',DRIVERS+'doc/wiki/2_RSI.md','rsi sensor interface ciclo tiempo real realtime'),
('kuka','EKI y mxAutomation','Interfaces KUKA que, en ciertas variantes del driver revisado, participan en la gestión del arranque y estado junto con RSI. No son sustitutos universales del intercambio cíclico.','Elegir la combinación documentada para el controlador, sus opciones y el modo de operación.',DRIVERS+'doc/wiki/2_RSI.md','eki ethernet krl mxautomation arranque estado'),
('kuka','FRI / Sunrise','Fast Robot Interface: interfaz externa utilizada en rutas de integración de robots LBR con Sunrise, con sus propios requisitos y versiones.','Es otra familia de integración. No copiar automáticamente una configuración RSI de KSS a un sistema Sunrise.',DRIVERS+'doc/wiki/3_Sunrise_FRI.md','fri lbr iiwa fast robot interface sunrise')
]
CATEGORIES={'fundamentos':'ROS 2 y archivos','red':'Comunicación y red','modelos':'Modelos y simulación','control':'Planificación y control','kuka':'Hardware KUKA'}

def render():
 p=ROOT/'index.html';s=BeautifulSoup(p.read_text(encoding='utf8'),'html.parser')
 for old in s.select('#conceptos, .reading-route'):old.decompose()
 rows=[]
 for cat,term,definition,example,url,aliases in TERMS:
  assert url.startswith('https://')
  rows.append(f'<tr data-category="{cat}" data-aliases="{escape(aliases,quote=True)}"><th scope="row"><strong>{escape(term)}</strong><span>{CATEGORIES[cat]}</span></th><td data-label="Qué significa">{escape(definition)}</td><td data-label="En esta celda">{escape(example)}</td><td data-label="Para aprender"><a href="{escape(url,quote=True)}" target="_blank" rel="noopener">Documentación de {escape(term)} <span aria-hidden="true">↗</span></a></td></tr>')
 options=''.join(f'<option value="{key}">{value}</option>' for key,value in CATEGORIES.items())
 section=f'''<section id="conceptos" class="wrap concept-reference" aria-labelledby="glossary-heading">
 <details id="glossary"><summary id="glossary-summary"><span class="glossary-icon" aria-hidden="true">Aa</span><span><strong id="glossary-heading">Glosario para repasar los conceptos</strong><span class="glossary-subtitle">{len(TERMS)} conceptos · definición, aplicación en esta celda y referencia</span></span><span class="glossary-action"><span class="glossary-state">Consultar</span> <span class="glossary-chevron" aria-hidden="true">+</span></span></summary>
 <div class="glossary-body"><p class="glossary-intro">Consulta esta tabla cuando una sigla interrumpa la lectura. Las definiciones explican el concepto; la columna «En esta celda» lo relaciona con el diseño propuesto y el repositorio revisado.</p><p class="glossary-distinction"><strong>ROS 2</strong> conecta los componentes. <strong>MoveIt 2</strong> planifica movimiento. <strong>Gazebo</strong> simula el robot. Cumplen funciones diferentes.</p>
 <div class="glossary-filters"><label class="field">Buscar un concepto<input id="glossary-search" type="search" placeholder="Ej.: DDS, dominio, MoveIt, YAML…" autocomplete="off" aria-controls="glossary-rows"/></label><label class="field">Área de estudio<select id="glossary-category" aria-controls="glossary-rows"><option value="all">Todas las áreas</option>{options}</select></label><button type="button" class="button ghost" id="glossary-reset">Mostrar todos</button></div>
 <p id="glossary-count" class="glossary-count" role="status" aria-live="polite">{len(TERMS)} conceptos disponibles</p>
 <div class="glossary-table-scroll" role="region" aria-label="Tabla de conceptos con desplazamiento propio" tabindex="0"><table class="glossary-table"><caption>Definiciones y lecturas de apoyo · base ROS 2 Humble cuando corresponde</caption><thead><tr><th scope="col">Concepto</th><th scope="col">Qué significa</th><th scope="col">En esta celda</th><th scope="col">Para aprender más</th></tr></thead><tbody id="glossary-rows">{''.join(rows)}</tbody></table><p id="glossary-empty" hidden>No hay coincidencias. Prueba otra palabra o selecciona «Mostrar todos».</p></div>
 <div class="glossary-footer"><p>La tabla tiene desplazamiento propio. Las referencias se abren en otra pestaña; no hace falta leerlas todas para seguir el recorrido.</p><button type="button" class="text-button" id="glossary-close">Cerrar glosario</button></div>
 </div></details></section>'''
 guide='''<aside class="wrap reading-route" aria-label="Cómo recorrer esta guía"><p>Cómo recorrer esta guía</p><ol><li><a href="#mapas"><span>01</span><strong>Comprender el sistema</strong><small>Empieza por el mapa sencillo.</small></a></li><li><a href="#conceptos"><span>02</span><strong>Aclarar los conceptos</strong><small>Abre el glosario cuando lo necesites.</small></a></li><li><a href="#implementacion"><span>03</span><strong>Revisar y practicar</strong><small>Consulta archivos y prueba el laboratorio.</small></a></li></ol></aside>'''
 first=s.select_one('#mapas');first.insert_before(BeautifulSoup(guide+section,'html.parser'))
 # Explain prerequisites before detailed files, then the local experiment.
 platform=s.select_one('.platform-section');s.select_one('#implementacion').insert_before(platform.extract())
 for selector,label in [('.platform-section .eyebrow','03 · BASE TÉCNICA Y CONTROLADOR'),('#implementacion .eyebrow','04 · ARCHIVOS, MENSAJES Y COMANDOS'),('#laboratorio .eyebrow','05 · PRÁCTICA DE COMUNICACIÓN'),('#ruta .eyebrow','06 · RUTA DE VALIDACIÓN'),('.questions-section .eyebrow','07 · PREGUNTAS FRECUENTES'),('#fuentes .eyebrow','08 · FUENTES Y CONTEXTO')]:
  s.select_one(selector).string=label
 nav=s.select_one('header nav')
 if not nav.select_one('a[href="#conceptos"]'):
  a=s.new_tag('a',href='#conceptos');a.string='Conceptos';nav.select_one('a').insert_after(a)
 for href,kind in [('glossary.css','link'),('glossary.js','script')]:
  if not s.select_one(f'{kind}[{"href" if kind=="link" else "src"}="{href}"]'):
   el=s.new_tag(kind,**({'href':href,'rel':'stylesheet'} if kind=='link' else {'src':href,'defer':''}));(s.head if kind=='link' else s.body).append(el)
 p.write_text(str(s),encoding='utf8')
 print(f'Added {len(TERMS)} concepts in {len(CATEGORIES)} areas. Glossary is closed by default.')

if __name__=='__main__':render()
